const recordMCPServerProbe = `-- name: RecordMCPServerProbe :one
UPDATE mcp_servers
SET consecutive_failures = CASE WHEN $1::boolean THEN 0 ELSE consecutive_failures + 1 END,
    health = CASE
               WHEN $1::boolean THEN 'healthy'::mcp_health
               WHEN consecutive_failures + 1 >= $2::int THEN 'unhealthy'::mcp_health
               ELSE health END,
    health_reason = CASE
               WHEN $1::boolean THEN NULL
               WHEN consecutive_failures + 1 >= $2::int THEN $3::text
               ELSE health_reason END,
    health_since = CASE
               WHEN (CASE WHEN $1::boolean THEN 'healthy'::mcp_health
                          WHEN consecutive_failures + 1 >= $2::int THEN 'unhealthy'::mcp_health
                          ELSE health END) IS DISTINCT FROM health
               THEN now() ELSE health_since END,
    health_checked_at = now(),
    tools_synced_at = CASE WHEN $1::boolean AND $4::boolean THEN now() ELSE tools_synced_at END
WHERE org_id = $5 AND id = $6
RETURNING org_id, id, name, url, transport, credential_header, credential_prefix, credential, source, managed_by_secret, declared_version, removed_at, disabled_reason, health, health_reason, health_checked_at, health_since, consecutive_failures, tools_synced_at, created_by, created_at, updated_at
`

